const SAFE = new Set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!$&'()*+,-.:;=@_~".split(''));
const VALID = /^(?:[A-Za-z0-9!$&'()*+,\-.:;=@_~]|%[0-9A-Fa-f]{2})*$/;
function segBytes(s){
  if(VALID.test(s)){
    const out=[]; let i=0;
    while(i<s.length){ if(s[i]==='%'){ out.push(parseInt(s.substr(i+1,2),16)); i+=3;} else {out.push(s.charCodeAt(i)); i++;} }
    return out;
  }
  return Array.from(Buffer.from(s,'utf8'));
}
function encSeg(bytes,qne){
  let o='';
  for(const b of bytes){ const c=String.fromCharCode(b);
    if(SAFE.has(c)) o+=c;
    else if(c==='?' && !qne) o+='?';
    else o+='%'+b.toString(16).toUpperCase().padStart(2,'0');
  }
  return o;
}
